// Use Gmail message ID as the primary identifier
const input = $json;
const id = input.id || input.messageId;

if (!id) {
  console.log('[SECRETARY] ERROR: No se pudo obtener el Gmail message ID');
  return [];
}

// Extract email data from payload if available
const payload = input.payload || {};
const headers = payload.headers ?? [];
const header = (name) => headers.find((h) => h.name?.toLowerCase() === name)?.value ?? '';

const subject = input.subject ?? header('subject') ?? '(sin asunto)';
const from = header('from') ?? header('From') ?? '(desconocido)';
const text = input.snippet ?? payload.textPlain ?? payload.body ?? '';

return [{ json: {
  ...input,
  email_id: id,
  item_key: `email:${id}`,
  subject,
  from,
  text,
  labelIds: input.labelIds ?? [],
  payload,
  received_at: new Date().toISOString()
} }];

const email = $('Preparar correo').item.json;
const status = $json.status;

if (status === 'duplicate') {
  console.log('[SECRETARY] Duplicado:', email.subject, '| ID:', email.item_key);
  return [];
}

if (status === 'new') {
  console.log('[SECRETARY] Nuevo:', email.subject, '| De:', email.from, '| ID:', email.item_key);
  return [{ json: { ...email, ...$json } }];
}

console.log('[SECRETARY] ERROR dedup - deteniendo email por seguridad:', email.subject, '| Status:', status);
return [];

const email = $('Preparar correo').item.json;
const fallback = {
  categoria: 'ignorar',
  accion: 'ignorar',
  prioridad: 'baja',
  confianza: 0,
  titulo: email.subject || '(sin asunto)',
  resumen: '',
  accion_requerida: '',
  fecha_inicio: null,
  hora_inicio: null,
  fecha_fin: null,
  hora_fin: null,
  fecha_limite: null,
  ubicacion: null,
  organizador: null,
  participantes: [],
  enlace: null,
  codigo_verificacion: null,
  requiere_intervencion_usuario: true,
  fallback: true
};

try {
  const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!raw) {
    console.log('[SECRETARY] Gemini sin contenido, usando fallback');
    return [{ json: { ...fallback, email, error: 'Gemini no devolvió contenido' } }];
  }

  let ai;
  try {
    ai = JSON.parse(raw);
  } catch (e) {
    console.log('[SECRETARY] JSON malformado de Gemini:', e.message);
    return [{ json: { ...fallback, email, error: 'JSON malformado: ' + e.message } }];
  }

  const required = ['categoria','accion','prioridad','confianza','titulo','resumen','accion_requerida','fecha_inicio','hora_inicio','fecha_fin','hora_fin','fecha_limite','ubicacion','organizador','participantes','enlace','codigo_verificacion','requiere_intervencion_usuario'];
  const missing = required.filter((key) => !Object.hasOwn(ai, key));
  if (missing.length > 0) {
    console.log('[SECRETARY] Campos faltantes en Gemini:', missing.join(', '));
    missing.forEach((key) => {
      if (key === 'categoria') ai.categoria = 'ignorar';
      if (key === 'accion') ai.accion = 'ignorar';
      if (key === 'prioridad') ai.prioridad = 'baja';
      if (key === 'confianza') ai.confianza = 0;
      if (key === 'titulo') ai.titulo = email.subject || '(sin asunto)';
      if (key === 'resumen') ai.resumen = '';
      if (key === 'accion_requerida') ai.accion_requerida = '';
      if (key === 'fecha_inicio') ai.fecha_inicio = null;
      if (key === 'hora_inicio') ai.hora_inicio = null;
      if (key === 'fecha_fin') ai.fecha_fin = null;
      if (key === 'hora_fin') ai.hora_fin = null;
      if (key === 'fecha_limite') ai.fecha_limite = null;
      if (key === 'ubicacion') ai.ubicacion = null;
      if (key === 'organizador') ai.organizador = null;
      if (key === 'participantes') ai.participantes = [];
      if (key === 'enlace') ai.enlace = null;
      if (key === 'codigo_verificacion') ai.codigo_verificacion = null;
      if (key === 'requiere_intervencion_usuario') ai.requiere_intervencion_usuario = true;
    });
  }

  const validCategories = ['agenda','tarea','importante','cuenta','seguridad','personal','laboral','ignorar'];
  if (!validCategories.includes(ai.categoria)) {
    console.log('[SECRETARY] Categoría inválida:', ai.categoria, '→ ignorar');
    ai.categoria = 'ignorar';
  }

  const validActions = ['crear_evento','actualizar_evento','cancelar_evento','crear_tarea','notificar','procesar','ignorar'];
  if (!validActions.includes(ai.accion)) {
    console.log('[SECRETARY] Acción inválida:', ai.accion, '→ ignorar');
    ai.accion = 'ignorar';
  }

  const validPriorities = ['alta','media','baja'];
  if (!validPriorities.includes(ai.prioridad)) {
    ai.prioridad = 'baja';
  }

  if (typeof ai.confianza !== 'number' || isNaN(ai.confianza) || ai.confianza < 0 || ai.confianza > 1) {
    ai.confianza = 0;
  }

  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (ai.fecha_inicio && !dateRegex.test(ai.fecha_inicio)) { ai.fecha_inicio = null; }
  if (ai.fecha_fin && !dateRegex.test(ai.fecha_fin)) { ai.fecha_fin = null; }
  if (ai.fecha_limite && !dateRegex.test(ai.fecha_limite)) { ai.fecha_limite = null; }

  const timeRegex = /^\d{2}:\d{2}$/;
  if (ai.hora_inicio && !timeRegex.test(ai.hora_inicio)) { ai.hora_inicio = null; }
  if (ai.hora_fin && !timeRegex.test(ai.hora_fin)) { ai.hora_fin = null; }

  if (ai.participantes && !Array.isArray(ai.participantes)) {
    ai.participantes = [];
  }

  if (ai.requiere_intervencion_usuario !== true && ai.requiere_intervucion_usuario !== false) {
    ai.requiere_intervencion_usuario = true;
  }

  console.log('[SECRETARY] Clasificado:', ai.categoria, '| Acción:', ai.accion, '| Prioridad:', ai.prioridad, '| Confianza:', ai.confianza);
  return [{ json: { ...ai, email, fallback: false } }];
} catch (e) {
  console.log('[SECRETARY] Error inesperado en validación:', e.message);
  return [{ json: { ...fallback, email, error: 'Error inesperado: ' + e.message } }];
}

const email = $('Preparar correo').item.json;
const ai = $json;

console.log('[SECRETARY] Procesando:', ai.categoria, '| Acción:', ai.accion, '| Prioridad:', ai.prioridad);
return [{ json: { ...ai, email } }];

const ai = $json;
const email = $('Preparar correo').item.json;

// Validación estricta: requiere fecha e hora de inicio
if (!ai.fecha_inicio || !ai.hora_inicio || ai.confianza < 0.85) {
  console.log('[SECRETARY] ERROR: crear_evento requiere fecha_inicio y hora_inicio con confianza >= 0.85');
  console.log('[SECRETARY] fecha_inicio:', ai.fecha_inicio, '| hora_inicio:', ai.hora_inicio, '| confianza:', ai.confianza);
  return [{ json: { ...ai, email, notification: 'event-incomplete' } }];
}

const now = new Date();
const eventDate = new Date(ai.fecha_inicio + 'T' + ai.hora_inicio + ':00');
if (eventDate <= now) {
  console.log('[SECRETARY] Evento no es futuro:', eventDate);
  return [{ json: { ...ai, email, notification: 'event-past' } }];
}

const event = {
  summary: ai.titulo || email.subject || '(sin asunto)',
  description: ai.resumen || ai.accion_requerida || '',
  location: ai.ubicacion || '',
  start: {
    dateTime: ai.fecha_inicio + 'T' + ai.hora_inicio + ':00',
    timeZone: $env.TZ || 'Europe/Madrid'
  },
  end: {
    dateTime: ai.fecha_fin && ai.hora_fin
      ? ai.fecha_fin + 'T' + ai.hora_fin + ':00'
      : ai.fecha_inicio + 'T' + ai.hora_inicio + ':00',
    timeZone: $env.TZ || 'Europe/Madrid'
  },
  attendees: ai.participantes && Array.isArray(ai.participantes)
    ? ai.participantes.map(p => ({ email: p, responseStatus: 'accepted' }))
    : [],
  conferenceData: ai.enlace ? {
    createRequest: {
      requestId: ai.titulo || email.subject || 'unknown',
      conferenceSolutionKey: { type: 'hangoutsMeet' }
    }
  } : undefined
};

if (ai.organizador) {
  event.description += (event.description ? '\n\n' : '') + 'Organizador: ' + ai.organizador;
}

if (ai.enlace) {
  event.description += (event.description ? '\n\n' : '') + 'Enlace: ' + ai.enlace;
}

return [{ json: { action: 'crear_evento', event, ai, email } }];

const ai = $json;
const email = $('Preparar correo').item.json;

if (ai.confianza < 0.85) {
  console.log('[SECRETARY] ERROR: actualizar_evento requiere confianza >= 0.85');
  return [{ json: { ...ai, email, notification: 'update-no-confidence' } }];
}

if (!ai.titulo && !ai.fecha_inicio && !ai.hora_inicio) {
  console.log('[SECRETARY] ERROR: actualizar_evento requiere información para identificar evento');
  return [{ json: { ...ai, email, notification: 'update-no-info' } }];
}

console.log('[SECRETARY] Actualizar evento:', ai.titulo, ai.fecha_inicio, ai.hora_inicio);
return [{ json: { action: 'actualizar_evento', ai, email } }];

const ai = $json;
const events = $json;
const email = $('Preparar correo').item.json;

const matchingEvent = events?.find(e => {
  const eventStart = e.start?.dateTime || e.start?.date;
  if (!eventStart) return false;
  return eventStart.includes(ai.fecha_inicio || '') && (ai.hora_inicio ? eventStart.includes(ai.hora_inicio) : true);
}) || events?.[0];

if (!matchingEvent) {
  console.log('[SECRETARY] No se encontró evento para actualizar');
  return [{ json: { ...ai, email, notification: 'update-no-match' } }];
}

const update = {};
if (ai.titulo) update.summary = ai.titulo;
if (ai.resumen) update.description = ai.resumen;
if (ai.ubicacion) update.location = ai.ubicacion;
if (ai.fecha_inicio && ai.hora_inicio) {
  update.start = { dateTime: ai.fecha_inicio + 'T' + ai.hora_inicio + ':00', timeZone: $env.TZ || 'Europe/Madrid' };
}
if (ai.fecha_fin && ai.hora_fin) {
  update.end = { dateTime: ai.fecha_fin + 'T' + ai.hora_fin + ':00', timeZone: $env.TZ || 'Europe/Madrid' };
}

console.log('[SECRETARY] Actualizando evento', matchingEvent.id, 'con:', update);
return [{ json: { action: 'actualizar_evento', eventId: matchingEvent.id, update, ai, email } }];

const ai = $json;
const email = $('Preparar correo').item.json;

if (ai.confianza < 0.85) {
  console.log('[SECRETARY] ERROR: cancelar_evento requiere confianza >= 0.85');
  return [{ json: { ...ai, email, notification: 'cancel-no-confidence' } }];
}

if (!ai.titulo && !ai.fecha_inicio && !ai.hora_inicio) {
  console.log('[SECRETARY] ERROR: cancelar_evento requiere información para identificar evento');
  return [{ json: { ...ai, email, notification: 'cancel-no-info' } }];
}

console.log('[SECRETARY] Cancelar evento:', ai.titulo, ai.fecha_inicio, ai.hora_inicio);
return [{ json: { action: 'cancelar_evento', ai, email } }];

const ai = $json;
const events = $json;
const email = $('Preparar correo').item.json;

const matchingEvent = events?.find(e => {
  const eventStart = e.start?.dateTime || e.start?.date;
  if (!eventStart) return false;
  return eventStart.includes(ai.fecha_inicio || '') && (ai.hora_inicio ? eventStart.includes(ai.hora_inicio) : true);
}) || events?.[0];

if (!matchingEvent) {
  console.log('[SECRETARY] No se encontró evento para cancelar');
  return [{ json: { ...ai, email, notification: 'cancel-no-match' } }];
}

console.log('[SECRETARY] Cancelando evento', matchingEvent.id);
return [{ json: { action: 'cancelar_evento', eventId: matchingEvent.id, ai, email } }];

const ai = $json;
const email = $('Preparar correo').item.json;

console.log('[SECRETARY] Enviar notificación de tarea:', ai.titulo);
return [{ json: { ...ai, email, notification: 'task-notification' } }];

const ai = $json;
const email = $('Preparar correo').item.json;

console.log('[SECRETARY] Enviar notificación importante:', ai.titulo);
return [{ json: { ...ai, email, notification: 'important-notification' } }];

const ai = $json;
const email = $('Preparar correo').item.json;

console.log('[SECRETARY] Enviar notificación procesar (seguridad/cuenta):', ai.titulo);
return [{ json: { ...ai, email, notification: 'process-notification' } }];
